from fractions import Fraction

def solution(events, window, k):
    # Recount every ad from scratch over the whole list: O(ads * n).
    if not events:
        return []
    cutoff = events[-1][0] - window
    ads = []
    for event in events:
        if event[1] not in ads:
            ads.append(event[1])
    rows = []
    for ad in ads:
        imps = 0
        clicks = 0
        for ts, other, kind in events:
            if other == ad and ts > cutoff:
                if kind == "imp":
                    imps += 1
                else:
                    clicks += 1
        if imps > 0:
            rows.append((-Fraction(clicks, imps), -imps, ad))
    rows.sort()
    return [row[2] for row in rows[:k]]
